import {readState,mutateState,emptyState,lessonKey,storeKey,valueOf,stats,isFilled,invalidate,escapeHTML as e,download,STORAGE_KEY,validateState,FIRST_LESSON,REFLECT,NOT_YET,reflectField,notYetOf,isDeferred} from './learning-store.js?v=ev45';
const root=document.querySelector('#learning-root');
// ?reset-answers empties every saved answer, completed lesson and task in this browser (course access is kept).
{const q=new URLSearchParams(location.search);if(q.has('reset-answers')){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(emptyState()));}catch{}q.delete('reset-answers');history.replaceState(history.state,'',location.pathname+(q.size?`?${q}`:'')+location.hash);}}
let state;let storageError='';try{state=readState();}catch(err){state=emptyState();storageError='Saved work could not be loaded. Storage may be unavailable or the saved file may be damaged. Your existing data has not been overwritten. You can export this session or restore a backup from Your Organisation.';}
const urlFor=(m,l)=>`/${lessonPath(m,l)}`;
// Which lesson this page shows: a lesson page carries it on <body>; learn.html?module=&lesson= (old links) in the query.
const where=()=>{const b=document.body.dataset,q=new URLSearchParams(location.search);return {module:b.module??q.get('module'),lesson:b.lesson??q.get('lesson')};};
// Pages use <base href="/">, so in-page links (#watch, #main) are handled here instead of resolving to the home page.
document.addEventListener('click',event=>{const a=event.target.closest('a[href^="#"]');if(!a||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey)return;const id=decodeURIComponent(a.getAttribute('href').slice(1));const target=document.getElementById(id);if(!target)return;event.preventDefault();history.replaceState(history.state,'',location.pathname+location.search+'#'+id);target.scrollIntoView({block:'start'});if(!target.hasAttribute('tabindex'))target.setAttribute('tabindex','-1');target.focus({preventScroll:true});});
const lessonNo=(m,l)=>`${m.no??m.id}.${m.lessons.indexOf(l)+1}`;
const toolName=p=>courseToolLabels[p.slug]||p.name;
