 pdfButton(document.querySelector('#all-pdfs'),async()=>{for(const x of m.lessons.filter(y=>!y.review&&y.fields?.some(f=>!f.store||f.full))){await lessonPDF(m,x);await new Promise(r=>setTimeout(r,400));}});
 const banner=document.querySelector('.saved-banner');if(banner){const bm=moduleFor(banner.dataset.module),bl=bm.lessons.find(x=>x.id===banner.dataset.lesson);pdfButton(document.querySelector('#saved-pdf'),()=>lessonPDF(bm,bl));}
