function bindTasks(m,l){const editor=document.querySelector('#task-editor');if(!editor)return;editor.addEventListener('input',event=>{const index=Number(event.target.dataset.task),field=event.target.dataset.field;if(!Number.isInteger(index)||!['title','owner','start','end'].includes(field))return;const value=event.target.value;const ok=save(s=>{if(s.tasks[index])s.tasks[index][field]=value;invalidate(s,m,l);});document.querySelector('#quality-check').checked=false;status(ok?'Work plan draft saved.':storageError,!ok);document.querySelector('#timeline-preview').innerHTML=timeline();});editor.addEventListener('click',event=>{if(event.target.id==='add-task'){if(state.tasks.length>=200){status('This course planner supports up to 200 tasks.',true);return;}const ok=save(s=>{s.tasks.push({id:`task-${Date.now()}`,title:'',owner:'',start:'',end:''});invalidate(s,m,l);});editor.innerHTML=taskEditor();status(ok?'Task added.':storageError,!ok);}if(event.target.hasAttribute('data-remove-task')){const index=Number(event.target.dataset.removeTask);const removed=state.tasks[index];const ok=save(s=>{s.tasks.splice(index,1);invalidate(s,m,l);});editor.innerHTML=taskEditor();status(ok?'Draft task removed. Use Undo if needed.':storageError,!ok);const undo=document.createElement('button');undo.type='button';undo.className='plain-button';undo.textContent='Undo removed task';undo.onclick=()=>{save(s=>{s.tasks.splice(index,0,removed);});editor.innerHTML=taskEditor();undo.remove();};document.querySelector('#save-status').append(undo);}});}
function markdown(selected=modules,heading='Your Organisation',source='Planning System'){return `# ${heading}\n\n${source} course work · ${new Date().toISOString().slice(0,10)}\n\n`+selected.map(m=>`## Module ${moduleNumber(m)}. ${m.output}\n\nStatus: ${stats(state,m).done}/${m.lessons.length} lessons complete\n\n`+m.lessons.filter(l=>!l.review).map(l=>`### ${lessonNo(m,l)} ${l.title}\n\n`+(notYetOf(state,m,l)!==null?`> Open item · Not relevant yet. ${notYetOf(state,m,l).trim()?`The trigger will be: ${notYetOf(state,m,l).trim()}`:'No trigger written yet.'}\n\n`:'')+(reflectField(l)&&answerOf(m,l,reflectField(l)).trim()?`**Reflect: ${l.reflect}**\n\n${answerOf(m,l,reflectField(l)).trim()}\n\n`:'')+(l.fields||[]).map(f=>`**${f.label}**\n\n${state.answers[lessonKey(m,l)]?.[f.key]||'Not yet drafted'}\n\n`).join('')+(l.id==='timeline'?state.tasks.map(t=>`- ${t.title} | ${t.owner} | ${t.start} → ${t.end}`).join('\n')+'\n\n':'')).join('')+(synthesisAnswers(m).some(x=>x.value)?`### Pulling it together\n\n`+synthesisAnswers(m).map(x=>`**${x.label}**\n\n${x.value||'Not yet answered'}\n\n`).join(''):'')).join('\n');}
// ---------- PDF downloads: the learner's own document, designed, with a short "created in" note at the end ----------
const orgName=()=>(state.answers[`${ansBase}.profile`]?.name||state.answers['0.profile']?.name||state.answers[`${FOUNDER_OFFSET}.profile`]?.name||'').trim();
const docTitle=l=>l.title.replace(/^Your\s+/i,'').replace(/^./,c=>c.toUpperCase());
const today=()=>new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});
const fieldsOf=(m,l)=>{const t=notYetOf(state,m,l),r=reflectField(l),rv=r?answerOf(m,l,r).trim():'';return [...(t!==null?[{label:'Open item · Not relevant yet',value:t.trim()?`The trigger will be: ${t.trim()}`:'No trigger written yet.'}]:[]),...(rv?[{label:`Reflect: ${r.label}`,value:rv}]:[])].concat((l.fields||[]).map(f=>{const value=answerOf(m,l,f);return {label:f.label,value,section:f.section,...fieldView(f,value)};})).concat(l.id==='timeline'&&state.tasks.length?[{label:'Work plan tasks',value:state.tasks.map(t=>`• ${t.title} — ${t.owner} — ${t.start} to ${t.end}`).join('\n')}]:[]);};
async function lessonPDF(m,l){const {downloadPDF,slug}=await import('./assets/js/lesson-pdf.js?v=15');const title=docTitle(l),org=orgName();await downloadPDF({title,orgName:org,subtitle:`Draft · ${today()}`,sections:[{fields:fieldsOf(m,l)}],created:{course:`Created in ${courseLabel(courseFor(m))}`,detail:`Module ${moduleNumber(m)} · ${m.title} · Lesson ${lessonNo(m,l)} ${l.title} · methodintoimpact.com`},filename:`${[slug(org),slug(title)].filter(Boolean).join('-')}.pdf`});}
// One-page summaries for the module outputs that people share most
let ansBase=0;const ans=(mid,lid,key)=>{const id=mid+ansBase;{const mm=moduleFor(id),ll=mm?.lessons.find(x=>x.id===lid);if(ll?.fields?.some(f=>f.edit)){const c=stagedColumn(mm,ll);if(c)return c;}}return state.answers[`${id}.${lid}`]?.[key]||moduleFor(id)?.lessons.map(x=>state.answers[`${id}.${x.id}`]?.[key]).find(Boolean)||'';};
const linesOf=(s,cols=2)=>String(s||'').split('\n').map(x=>x.split('|').map(y=>y.trim()).filter(Boolean).slice(0,cols).join(' · ')).filter(Boolean);
const st=(mid,lid,key,label)=>({type:'statement',label,text:ans(mid,lid,key)}),li=(mid,lid,key,label,cols=2)=>({type:'list',label,items:linesOf(ans(mid,lid,key),cols)});
