 'theory-of-change':()=>[{type:'statement',label:'The problem',text:ans(2,'problem','problem')},{type:'pathway',label:'The pathway, read from top to bottom',steps:[{label:'Inputs',text:ans(2,'inputs','inputs')},{label:'Activities',text:ans(2,'activities','activities')},{label:'Outputs',text:ans(2,'outputs','outputs')},{label:'Outcomes',text:ans(2,'outcomes','outcomes')},{label:'Long-term impact',text:ans(2,'impact','impact')}],note:{label:'Assumptions to test',text:ans(2,'assumptions','assumptions')}}]
