async function modulePDF(m){ansBase=isFounder(m)?FOUNDER_OFFSET:0;const {downloadPDF,slug}=await import('./assets/js/lesson-pdf.js?v=15');const org=orgName();await downloadPDF({title:m.output,orgName:org,subtitle:`Draft · ${today()}`,summary:moduleSummary[m.slug]?.(),sections:m.lessons.filter(l=>!l.review).map(l=>({eyebrow:`Lesson ${lessonNo(m,l)}`,heading:l.title,fields:fieldsOf(m,l)})).concat(synthesisAnswers(m).some(x=>x.value)?[{eyebrow:'Module review',heading:'Pulling it together',fields:synthesisAnswers(m)}]:[]),created:{course:`Created in ${courseLabel(courseFor(m))}`,detail:`Module ${moduleNumber(m)} · ${m.title} · methodintoimpact.com`},filename:`${[slug(org),slug(m.output)].filter(Boolean).join('-')}.pdf`});}
function pdfButton(button,make){button?.addEventListener('click',async()=>{const label=button.textContent;button.disabled=true;button.textContent='Preparing PDF…';try{await make();}catch(err){status('The PDF could not be created on this browser. Your work is still saved; try again or use another browser.',true);}finally{button.disabled=false;button.textContent=label;}});}
const SAVED_FLAG='mi-just-saved';
function savedBanner(){let key;try{key=sessionStorage.getItem(SAVED_FLAG);sessionStorage.removeItem(SAVED_FLAG);}catch{return '';}if(!key)return '';const [id,...rest]=key.split('.');const m=moduleFor(id),l=m?.lessons.find(x=>x.id===rest.join('.'));if(!m||!l||l.review)return '';return `<div class="saved-banner" role="status" data-module="${m.id}" data-lesson="${e(l.id)}"><span>✓ Saved: <b>${lessonNo(m,l)} ${e(l.title)}</b></span><button type="button" class="button ghost" id="saved-pdf">Download it as a PDF ↓</button></div>`;}
function renderOrganisation(){const f=new URLSearchParams(location.search).get('track')==='entrepreneurs';ansBase=f?FOUNDER_OFFSET:0;const list=f?founderModules:modules,courseList=f?founderPhases:phases;const progress=stats(state,null,list);const anyFounder=founderModules.some(x=>x.lessons.some(l=>state.answers[lessonKey(x,l)]||state.completed[lessonKey(x,l)]));root.innerHTML=`<div class="output-pack"><nav class="breadcrumbs">${f?'<a href="courses-entrepreneurs.html">Courses for entrepreneurs</a>':'<a href="planning-system.html">Planning System</a>'}<span>› Your Organisation</span></nav>${f?'<p class="course-tag">For entrepreneurs · your work from the four courses for entrepreneurs. <a href="organisation.html">Organisation courses pack →</a></p>':anyFounder?'<p class="course-tag">Also taking the courses for entrepreneurs? <a href="organisation.html?track=entrepreneurs">See that pack →</a></p>':''}<span class="eyebrow">Your course strategy pack</span><h1>Your Organisation</h1><p>Each lesson adds to an output you can review, revise and use. ${f?'':'This pack brings together your course work; it does not connect separate software products.'}</p><p><b>${progress.done} of ${progress.total} lessons complete · ${progress.percent}%</b></p><progress aria-label="Planning System progress" value="${progress.percent}" max="100"></progress>${coursesProgress(courseList)}${openItems(list)}<p id="save-status" role="status" class="saved-status ${storageError?'error':''}">${e(statusText())}</p><div class="toolbar no-print"><a class="button" href="${f?resumeCourseList(courseList):resumeURL()}">Continue learning →</a><button class="button ghost" id="download-pack">Download strategy pack</button><button class="plain-button" id="print-pack">Print / save PDF</button></div><details class="no-print resource-panel"><summary>Back up or restore your work</summary><p>A backup includes your course answers and progress. Import replaces this browser’s current course work after you review the file. Backups from the earlier eight-module course are moved to the new lessons automatically. It never grants paid access.</p><button class="button ghost" id="backup">Download backup</button><label class="field-label" for="restore">Choose a backup to review</label><input type="file" id="restore" accept=".json,application/json"><p id="import-status" role="status"></p></details>${courseList.map(p=>`<h2 class="phase-heading">${e(courseLabel(p))} <small>${e(p.summary)}</small></h2>${list.filter(m=>m.phase===p.name).map(m=>`<details class="output-section"><summary><span>Module ${moduleNumber(m)} · ${e(m.output)}</span><small>${stats(state,m).done}/${m.lessons.length} complete${stats(state,m).done===m.lessons.length?' · ✓ Completed':''}</small></summary><section><div class="section-head"><div><span class="eyebrow">Module ${moduleNumber(m)} · ${stats(state,m).done===m.lessons.length?'Completed':stats(state,m).done?'In progress':'Not completed'}</span><h2>${e(m.output)}</h2></div></div><p class="subtle">${stats(state,m).done}/${m.lessons.length} lessons complete</p>${special(m)}${output(m)}${synthesisView(m)}</section></details>`).join('')}`).join('')}</div><dialog class="import-dialog" id="import-dialog"><h2>Restore course backup?</h2><p id="import-summary"></p><p>This replaces your current course answers and progress on this browser. Download a backup first if you want to keep both versions.</p><div class="toolbar"><button class="button ghost" id="keep-backup">Back up current work</button><button class="button" id="confirm-import">Restore this file</button><button class="plain-button" id="cancel-import">Cancel</button></div></dialog>`;
 document.querySelector('#download-pack').onclick=()=>download(f?'founder-strategy-pack.md':'organisation-strategy-pack.md',f?markdown(founderModules,'Your Organisation','Courses for entrepreneurs'):markdown());document.querySelector('#print-pack').onclick=()=>{document.querySelectorAll('.output-section').forEach(d=>d.open=true);window.print();};const backup=()=>download('planning-system-backup.json',JSON.stringify(state,null,2),'application/json');document.querySelector('#backup').onclick=backup;document.querySelector('#keep-backup').onclick=backup;const dialog=document.querySelector('#import-dialog');let incoming=null;document.querySelector('#cancel-import').onclick=()=>{incoming=null;dialog.close();};document.querySelector('#restore').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>2000000)throw new Error('Choose a backup smaller than 2 MB.');incoming=validateState(JSON.parse(await file.text()));document.querySelector('#import-summary').textContent=`This file contains ${Object.keys(incoming.answers).length} lesson drafts, ${stats(incoming).done} completed lessons and ${incoming.tasks.length} tasks.`;dialog.showModal();}catch(err){document.querySelector('#import-status').textContent=`Could not import: ${err.message}`;}};document.querySelector('#confirm-import').onclick=()=>{if(!incoming)return;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(incoming));state=incoming;storageError='';dialog.close();renderOrganisation();status('Backup restored on this browser.');}catch(err){document.querySelector('#import-summary').textContent='Storage is unavailable. Your existing work has not been replaced.';}};
}
const resumeCourseList=list=>{for(const p of list)for(const x of courseModules(p))for(const l of x.lessons)if(!state.completed[lessonKey(x,l)])return urlFor(x,l);return firstLessonOf(list[0]);};
export function resumeURL(){const [id,...parts]=(state.lastLesson||FIRST_LESSON).split('.');const m=moduleFor(id),l=m?.lessons.find(x=>x.id===parts.join('.'));return m&&l?urlFor(m,l):`learn.html?module=${id}&lesson=${parts.join('.')}`;}
if(root){if(document.body.dataset.page==='organisation')renderOrganisation();else renderLesson();}
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY){status('Course work changed in another tab. Reload before continuing here so you can review the latest version.',true);document.querySelectorAll('#lesson-form input,#lesson-form textarea,#lesson-form button,#review-form input,#review-form button,#synthesis-form textarea').forEach(b=>b.disabled=true);}});
window.addEventListener('pageshow',event=>{if(event.persisted)location.reload();}); // back/forward: show the latest progress
